                    throw OpenAPITransportError.badURLError()
                }
                var localVarPath = "/vector_stores/{vector_store_id}"
                localVarPath = localVarPath.replacingOccurrences(of: "{vector_store_id}", with: vectorStoreId)
                let localVarURL = baseURL.appendingPathComponent(localVarPath)
                let components = URLComponents(url: localVarURL, resolvingAgainstBaseURL: false)
                guard let requestURL = components?.url else {
                    throw OpenAPITransportError.badURLError()
                }
                var request = URLRequest(url: requestURL)
                request.httpMethod = "POST"
                request.httpBody = try self.encoder.encode(updateVectorStoreRequest)
                request.setValue("application/json", forHTTPHeaderField: "Content-Type")
                return request
            }.publisher
        }.flatMap { request -> AnyPublisher<VectorStoreObject, Error> in 
            return self.transport.send(request: request)
                .tryMap { response in
                    try self.decoder.decode(VectorStoreObject.self, from: response.data)
                }
                .eraseToAnyPublisher()
        }.eraseToAnyPublisher()
    }
}
